import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 1_000_000_007L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int head = 0, tail = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() {
            if (head >= tail) {
                head = 0;
                try {
                    tail = in.read(buffer, 0, buffer.length);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (tail <= 0) return -1;
            }
            return buffer[head++];
        }

        public long nextLong() {
            int c = read();
            while (c <= 32) {
                if (c == -1) return -1;
                c = read();
            }
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long res = 0;
            while (c > 32) {
                res = res * 10 + c - '0';
                c = read();
            }
            return res * sign;
        }

        public int nextInt() {
            return (int) nextLong();
        }
    }

    static class Meal {
        long a, b;
        Meal(long a, long b) {
            this.a = a;
            this.b = b;
        }
    }

    static class Line {
        long a, b;
        Line(long a, long b) {
            this.a = a;
            this.b = b;
        }

        long eval(long x) {
            return a * x + b;
        }
    }

    static long power(long base, long exp) {
        long res = 1;
        base %= MOD;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return res;
    }

    static long modInverse(long n) {
        return power(n, MOD - 2);
    }

    public static void main(String[] args) throws IOException {
        FastScanner scanner = new FastScanner(System.in);
        int N = scanner.nextInt();
        int M = scanner.nextInt();
        long K = scanner.nextLong();

        long[] fa = new long[N];
        for (int i = 0; i < N; i++) fa[i] = scanner.nextLong();
        long[] fb = new long[N];
        for (int i = 0; i < N; i++) fb[i] = scanner.nextLong();

        Meal[] meals = new Meal[M];
        long[] ma = new long[M];
        for (int i = 0; i < M; i++) ma[i] = scanner.nextLong();
        for (int i = 0; i < M; i++) {
            meals[i] = new Meal(ma[i], scanner.nextLong());
        }

        // Ordenar as refeições:
        // i antes de j se b_i * (a_j - 1) > b_j * (a_i - 1)
        Arrays.sort(meals, (m1, m2) -> {
            // Comparar m1.b * (m2.a - 1) com m2.b * (m1.a - 1)
            // Os valores podem ser até 10^18, usamos BigInteger ou unsigned/double para segurança
            long left = m1.b * (m2.a - 1);
            long right = m2.b * (m1.a - 1);
            // Podem exceder Long.MAX_VALUE se m.b ~ 10^9 e m.a ~ 10^9 (10^18 cabe em long!)
            // 10^9 * 10^9 = 10^18 <= Long.MAX_VALUE (9.22 * 10^18)
            return Long.compare(right, left); // ordem decrescente
        });

        // Compor todas as refeições em R(x) = A_meals * x + B_meals
        long A_meals = 1;
        long B_meals = 0;
        for (int i = 0; i < M; i++) {
            A_meals = (A_meals * (meals[i].a % MOD)) % MOD;
            B_meals = ((B_meals * (meals[i].a % MOD)) % MOD + (meals[i].b % MOD)) % MOD;
        }

        // Preparar feitiços para o Upper Envelope
        // Se houver múltiplos feitiços com mesmo 'a', mantemos o com maior 'b'
        Map<Long, Long> bestB = new HashMap<>();
        for (int i = 0; i < N; i++) {
            long a = fa[i];
            long b = fb[i];
            bestB.put(a, Math.max(bestB.getOrDefault(a, -1L), b));
        }

        List<Line> lines = new ArrayList<>();
        for (Map.Entry<Long, Long> entry : bestB.entrySet()) {
            lines.add(new Line(entry.getKey(), entry.getValue()));
        }
        lines.sort(Comparator.comparingLong(l -> l.a));

        // Construir Convex Hull (Upper Envelope)
        List<Line> hull = new ArrayList<>();
        for (Line line : lines) {
            while (hull.size() >= 2) {
                Line l1 = hull.get(hull.size() - 2);
                Line l2 = hull.get(hull.size() - 1);
                // Interseção de l1 e l2 vs l2 e line
                // x_{1,2} = ceil((l1.b - l2.b) / (l2.a - l1.a))
                // l2 é redundante se x_{l1, line} <= x_{l1, l2}
                // (l1.b - line.b) / (line.a - l1.a) <= (l1.b - l2.b) / (l2.a - l1.a)
                // Usamos double ou BigInteger para evitar overflow no produto cruzado
                double num1 = (double) (l1.b - line.b);
                double den1 = (double) (line.a - l1.a);
                double num2 = (double) (l1.b - l2.b);
                double den2 = (double) (l2.a - l1.a);
                if (num1 / den1 <= num2 / den2) {
                    hull.remove(hull.size() - 1);
                } else {
                    break;
                }
            }
            hull.add(line);
        }

        int H = hull.size();
        // Pré-calcular pontos de transição x onde hull[i] passa para hull[i+1]
        // hull[i].a * x + hull[i].b < hull[i+1].a * x + hull[i+1].b
        // x * (hull[i+1].a - hull[i].a) > hull[i].b - hull[i+1].b
        long[] transX = new long[H - 1];
        for (int i = 0; i < H - 1; i++) {
            Line l1 = hull.get(i);
            Line l2 = hull.get(i + 1);
            long num = l1.b - l2.b;
            long den = l2.a - l1.a;
            // menor inteiro x tal que l2.eval(x) >= l1.eval(x)
            if (num <= 0) {
                transX[i] = 0;
            } else {
                transX[i] = (num + den - 1) / den;
            }
        }

        int Q = scanner.nextInt();
        StringBuilder out = new StringBuilder();

        for (int q = 0; q < Q; q++) {
            long x = scanner.nextLong();
            long remK = K;

            // Encontrar em qual linha do hull começamos
            int idx = 0;
            while (idx < H - 1 && x >= transX[idx]) {
                idx++;
            }

            // Simular enquanto remK > 0 e idx < H - 1
            while (remK > 0 && idx < H - 1) {
                Line cur = hull.get(idx);
                long nextX = transX[idx];

                if (cur.a == 1) {
                    long diff = nextX - x;
                    long stepsNeeded = (diff + cur.b - 1) / cur.b;
                    if (stepsNeeded <= 0) stepsNeeded = 1;
                    long take = Math.min(remK, stepsNeeded);
                    x += take * cur.b;
                    remK -= take;
                } else {
                    // a >= 2, x cresce exponencialmente
                    x = cur.eval(x);
                    remK--;
                }

                while (idx < H - 1 && x >= transX[idx]) {
                    idx++;
                }
            }

            // Agora remK passos restantes na linha hull[idx] (que é a última, ou remK zerou)
            long ansX;
            Line finalLine = hull.get(idx);
            if (remK == 0) {
                ansX = x % MOD;
            } else {
                long a = finalLine.a;
                long b = finalLine.b;
                if (a == 1) {
                    ansX = (x % MOD + (remK % MOD) * (b % MOD)) % MOD;
                } else {
                    // f^(K)(x) = a^K * x + b * (a^K - 1) / (a - 1)
                    long aPow = power(a, remK);
                    long term1 = (aPow * (x % MOD)) % MOD;
                    long num = (aPow - 1 + MOD) % MOD;
                    long denInv = modInverse((a - 1) % MOD);
                    long term2 = (b % MOD) * num % MOD * denInv % MOD;
                    ansX = (term1 + term2) % MOD;
                }
            }

            long total = (A_meals * ansX + B_meals) % MOD;
            out.append(total).append('\n');
        }

        System.out.print(out);
    }
}
