            // Encontrar em qual linha do hull começamos
            int idx = 0;
            while (idx < H - 1 && x >= transX[idx]) {
                idx++;
            }

            // Simular enquanto remK > 0 e idx < H - 1
            while (remK > 0 && idx < H - 1) {
                Line cur = hull.get(idx);
                long nextX = transX[idx];

                if (cur.a == 1) {
                    long diff = nextX - x;
                    long stepsNeeded = (diff + cur.b - 1) / cur.b;
                    if (stepsNeeded <= 0) stepsNeeded = 1;
                    long take = Math.min(remK, stepsNeeded);
                    x += take * cur.b;
                    remK -= take;
                } else {
                    // a >= 2, x cresce exponencialmente
                    x = cur.eval(x);
                    remK--;
                }

                while (idx < H - 1 && x >= transX[idx]) {
                    idx++;
                }
            }

            // Agora remK passos restantes na linha hull[idx] (que é a última, ou remK zerou)
            long ansX;
            Line finalLine = hull.get(idx);
            if (remK == 0) {
                ansX = x % MOD;
            } else {
                long a = finalLine.a;
                long b = finalLine.b;
                if (a == 1) {
                    ansX = (x % MOD + (remK % MOD) * (b % MOD)) % MOD;
                } else {
                    // f^(K)(x) = a^K * x + b * (a^K - 1) / (a - 1)
                    long aPow = power(a, remK);
                    long term1 = (aPow * (x % MOD)) % MOD;
                    long num = (aPow - 1 + MOD) % MOD;
                    long denInv = modInverse((a - 1) % MOD);
                    long term2 = (b % MOD) * num % MOD * denInv % MOD;
                    ansX = (term1 + term2) % MOD;
                }
            }

            long total = (A_meals * ansX + B_meals) % MOD;
            out.append(total).append('\n');
        }

        System.out.print(out);
    }
}
